CONDS = [
    ('breadth_open', '>', 0.65),
    ('new_lod', '==', 1.0),
    ('or_low_dist_atr', '<=', -0.24),
    ('sma20_dist_pct', '<=', -0.94),
]
LAYERS = ['breadth_open > 0.65', 'new_lod == 1', 'or_low_dist_atr <= -0.24', 'sma20_dist_pct <= -0.94', 'window 1300-1500']


def mask(df) -> np.ndarray:
    x = compute(df, names=['new_lod', 'or_low_dist_atr', 'sma20_dist_pct'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
    return np.asarray(m, dtype=bool)
